-- 301: Barrios y conjuntos de Cúcuta guardados en nuestra base (fuente: OpenStreetMap).
--
-- POR QUÉ (2026-10-03): el bot de WhatsApp le pedía el barrio a Nominatim (servicio público de
-- OpenStreetMap) en cada ubicación. Prueba real del usuario ese día, coordenadas
-- 7.9259865,-72.4963465: desde un PC Nominatim responde "La Insula", pero desde el servidor
-- de Supabase la consulta fallaba al instante (el bot contestó en el mismo segundo, sin agotar
-- su espera) -- Nominatim limita o bloquea servidores compartidos en la nube. Resultado: la
-- tarjeta del conductor sin barrio (caso Luis Felipe, viaje 265e13d0, mismo día).
--
-- Ahora el barrio sale de esta tabla con PostGIS: milisegundos, sin servicio externo.
-- Datos descargados de Overpass el 2026-10-03, caja 7.78,-72.60 a 8.00,-72.43 (área
-- metropolitana): 509 elementos.
--   tipo 'barrio'   = place=neighbourhood|suburb|quarter (punto o zona)
--   tipo 'conjunto' = landuse=residential con nombre (urbanizaciones/conjuntos, zona)
-- Para actualizar: volver a descargar y reemplazar el contenido (el TRUNCATE de abajo lo permite).
-- Datos © colaboradores de OpenStreetMap, licencia ODbL.

CREATE TABLE IF NOT EXISTS public.ag_barrios_osm (
  osm_ref text PRIMARY KEY,                  -- 'n<id>' nodo, 'w<id>' way de OSM
  nombre  text NOT NULL,
  tipo    text NOT NULL CHECK (tipo IN ('barrio', 'conjunto')),
  geom    extensions.geometry(Geometry, 4326) NOT NULL
);
CREATE INDEX IF NOT EXISTS ag_barrios_osm_geom_idx ON public.ag_barrios_osm USING gist (geom);
ALTER TABLE public.ag_barrios_osm ENABLE ROW LEVEL SECURITY;
-- Sin políticas a propósito: solo la edge function (service_role) la consulta, vía la RPC.

TRUNCATE public.ag_barrios_osm;
