-- Barrio y conjunto de un punto.
--   conjunto: la zona residencial con nombre que CONTIENE el punto (la más pequeña).
--   barrio:   la zona de barrio que contiene el punto; si no hay, el punto de barrio más
--             cercano a menos de 800 m (es lo mismo que hace Nominatim con los barrios que
--             OSM tiene solo como punto, que en Cúcuta son la mayoría).
CREATE OR REPLACE FUNCTION public.ag_barrio_en(p_lat double precision, p_lng double precision)
RETURNS TABLE (barrio text, conjunto text)
LANGUAGE sql STABLE
SET search_path = public, extensions
AS $$
  WITH p AS (SELECT ST_SetSRID(ST_MakePoint(p_lng, p_lat), 4326) AS g)
  SELECT
    COALESCE(
      (SELECT b.nombre FROM ag_barrios_osm b, p
        WHERE b.tipo = 'barrio' AND ST_GeometryType(b.geom) <> 'ST_Point' AND ST_Contains(b.geom, p.g)
        ORDER BY ST_Area(b.geom) LIMIT 1),
      (SELECT b.nombre FROM ag_barrios_osm b, p
        WHERE b.tipo = 'barrio' AND ST_GeometryType(b.geom) = 'ST_Point'
          AND ST_DWithin(b.geom::geography, p.g::geography, 800)
        ORDER BY b.geom::geography <-> p.g::geography LIMIT 1)
    ) AS barrio,
    (SELECT b.nombre FROM ag_barrios_osm b, p
      WHERE b.tipo = 'conjunto' AND ST_Contains(b.geom, p.g)
      ORDER BY ST_Area(b.geom) LIMIT 1) AS conjunto;
$$;

REVOKE ALL ON FUNCTION public.ag_barrio_en(double precision, double precision) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.ag_barrio_en(double precision, double precision) TO service_role;
